# Categorize by type based on name patterns
def categorize(exp_id):
    eid = exp_id.lower()
    if "re_" in eid or "_re_" in eid or eid.startswith("exp008") or "re " in eid:
        if "ner" in eid:
            return "Joint/Both"
        return "RE"
    if "ner" in eid:
        return "NER"
    if "joint" in eid:
        return "Joint/Both"
    if "ood" in eid or "cross" in eid:
        return "OOD/Transfer"
    if "ablation" in eid or "freeform" in eid:
        return "Ablation"
    if "signal" in eid or "bootstrap" in eid or "ensemble" in eid:
        return "Analysis/Signal"
    if "conll" in eid or "scierc" in eid:
        # Could be NER or joint - check metrics
        return "NER/Dataset"
    return "Other"

# Better categorization: look at metrics keys
def categorize_v2(exp_id, metrics):
    eid = exp_id.lower()
    has_ner = any("ner" in k.lower() for k in metrics.keys())
    has_re = any("re_" in k.lower() or k.lower().startswith("re") for k in metrics.keys())
    has_rho = any("rho" in k.lower() for k in metrics.keys())

    if "ood" in eid:
        return "OOD/Transfer"
    if "ablation" in eid or "freeform" in eid:
        return "Ablation"
    if "signal" in eid or "bootstrap" in eid or "ensemble" in eid:
        return "Analysis/Signal"
    if "018" in eid:
        return "Multi-model (exp_018)"
    if has_ner and has_re:
        return "Joint NER+RE"
    if has_re:
        return "RE"
    if has_ner:
        return "NER"
    if has_rho:
        return "Correlation/Selection"
    return "Other"

from collections import defaultdict
grouped = defaultdict(list)
for exp_id, exp in success_with_metrics:
    cat = categorize_v2(exp_id, exp["metrics"])
    grouped[cat].append((exp_id, exp))

for cat in sorted(grouped.keys()):
    print(f"\n--- {cat} ({len(grouped[cat])} experiments) ---")
    for exp_id, exp in grouped[cat]:
        metrics = exp["metrics"]
        # Summarize key metrics
        metric_summary = {}
        for k, v in metrics.items():
            if isinstance(v, (int, float)):
                metric_summary[k] = round(v, 4) if isinstance(v, float) else v
            elif isinstance(v, str) and len(v) < 50:
                metric_summary[k] = v
            elif isinstance(v, dict):
                metric_summary[k] = "{dict}"
            elif isinstance(v, list) and len(v) <= 4:
                metric_summary[k] = v
        print(f"  {exp_id}: {metric_summary}")

